const int step = static_cast<int>(std::sqrt(size));
int prev = 0;
while (arr[std::min(step, size) - 1] < target) {
    prev = step;
    step += static_cast<int>(std::sqrt(size));
    if (prev >= size) {
        return -1;
    }
}

while (arr[prev] < target) {
    prev++;
    if (prev == std::min(step, size)) {
        return -1;
    }
}

if (arr[prev] == target) {
    return prev;
}
return -1;
// END_CODE

